#pragma config(Motor, port1, testMotor, tmotorVex393_HBridge, openLoop)
#pragma config(Motor, port2, testServo, tmotorServoStandard, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
ENGR 10 Week 1 - 4.1.4 Check that motors are working
Turns the motor (port 1) back and forth, then moves the servo (port 2) to a set number of degrees.
Change the ports above if yours are plugged in somewhere else (servo on ports 2-9 needs a Motor Controller 29).
The VEX servo turns about 100 degrees in total: -50 to +50 degrees from the center.
*/
int servoDegrees = 45;       // how far to move the servo, -50 to 50

int DegreesToServo(int degrees)
{
	return degrees * 127 / 50;   // servo command -127..127 covers -50..+50 degrees
}

task main()
{
	// motor back and forth 3 times
	for(int i = 0; i < 3; i++)
	{
		motor[testMotor] = 80;    // forward
		wait1Msec(1500);
		motor[testMotor] = -80;   // backward
		wait1Msec(1500);
	}
	motor[testMotor] = 0;

	// servo: center, then +servoDegrees, then -servoDegrees, then back to center
	motor[testServo] = 0;
	wait1Msec(1000);
	motor[testServo] = DegreesToServo(servoDegrees);
	wait1Msec(1500);
	motor[testServo] = DegreesToServo(-servoDegrees);
	wait1Msec(1500);
	motor[testServo] = 0;
	wait1Msec(1000);
}
